		Path snapshot = alternate.resolve("synopsis/synopsis-v8.bin");
		assertTrue(Files.isRegularFile(snapshot, LinkOption.NOFOLLOW_LINKS), "setup: real alternate snapshot");
		Path marker = alternate.resolve("synopsis/synopsis-v8.rebuild");
